  "g7-1-c1/exponent-law-calculation": {
    "title": "利用指數律做計算",
    "chapter": "國一上｜數與數線",
    "section": "指數記法、指數律與科學記號",
    "quizId": "g7-1-c1",
    "topicId": "exponent-law-calculation",
    "blocks": [
      {
        "type": "text",
        "html": "<p><strong>利用指數律做計算</strong>屬於「指數記法、指數律與科學記號」。本題型在單元小考中固定出現一題；同一份試卷由<strong>種子碼</strong>決定使用 10 組變體中的哪一組。</p>"
      },
      {
        "type": "text",
        "html": "<p>把方向、大小與距離分開思考，是所有負數運算的地基。</p>"
      },
      {
        "type": "formula",
        "content": "|a| = a（a ≥ 0）；|a| = −a（a < 0）"
      },
      {
        "type": "text",
        "html": "<h4>解題流程</h4><ol><li>先圈出每個數前真正的符號</li><li>乘除先判正負，再算絕對值</li><li>加減改寫成加法；同號相加、異號相減</li><li>用估算或數線檢查正負方向</li></ol>"
      },
      {
        "type": "example",
        "q": "（例）利用指數律做計算：先讀題意，再依 指數記法、指數律與科學記號 的規則逐步計算或判斷。",
        "a": "對照選項或計算結果，確認符合 利用指數律做計算 的定義與條件。"
      },
      {
        "type": "pitfall",
        "html": "<p>連續兩個負號常變加號</p><p>−a 不一定是負數；若 a = −3，則 −a = 3。看到負號要先問：它是數的符號、相反數，還是減法？</p>"
      }
    ]
  },
