  "g7-1-c2/factor-and-multiple": {
    "title": "因數與倍數",
    "chapter": "國一上｜標準分解式與分數",
    "section": "因數和倍數與質因數分解",
    "quizId": "g7-1-c2",
    "topicId": "factor-and-multiple",
    "blocks": [
      {
        "type": "text",
        "html": "<p><strong>因數與倍數</strong>屬於「因數和倍數與質因數分解」。本題型在單元小考中固定出現一題；同一份試卷由<strong>種子碼</strong>決定使用 10 組變體中的哪一組。</p>"
      },
      {
        "type": "text",
        "html": "<p>把整數拆成質因數，公因數與公倍數就變成指數的選擇題。</p>"
      },
      {
        "type": "formula",
        "content": "a、b 作標準分解式後："
      },
      {
        "type": "text",
        "html": "<h4>解題流程</h4><ol><li>判斷題意要 gcd 或 lcm</li><li>用短除法或質因數分解</li><li>gcd 取共同且小；lcm 取全部且大</li><li>回到情境確認單位與是否要再加一次週期</li></ol>"
      },
      {
        "type": "example",
        "q": "（例）因數與倍數：先讀題意，再依 因數和倍數與質因數分解 的規則逐步計算或判斷。",
        "a": "對照選項或計算結果，確認符合 因數與倍數 的定義與條件。"
      },
      {
        "type": "pitfall",
        "html": "<p>連續整數通常互質</p><p>問『最多分成幾組、每組一樣且分完』多半找最大公因數；問『最少多久同時、最小共同數量』多半找最小公倍數。</p>"
      }
    ]
  },
