  "g7-1-c3/literal-expression-setup": {
    "title": "文字符號的列式",
    "chapter": "國一上｜一元一次方程式",
    "section": "文字符號的列式與運算",
    "quizId": "g7-1-c3",
    "topicId": "literal-expression-setup",
    "blocks": [
      {
        "type": "text",
        "html": "<p><strong>文字符號的列式</strong>屬於「文字符號的列式與運算」。本題型在單元小考中固定出現一題；同一份試卷由<strong>種子碼</strong>決定使用 10 組變體中的哪一組。</p>"
      },
      {
        "type": "text",
        "html": "<p>方程式像天平；每一步都對兩邊做相同操作，平衡就不會壞。</p>"
      },
      {
        "type": "formula",
        "content": "ax＋b＝c（a≠0） ⇒ x＝[[frac:c−b|a]]"
      },
      {
        "type": "text",
        "html": "<h4>解題流程</h4><ol><li>設未知數並寫清楚單位</li><li>依題意列等量關係</li><li>去括號、去分母、合併同類項</li><li>解出後代回原題檢查</li></ol>"
      },
      {
        "type": "example",
        "q": "（例）文字符號的列式：先讀題意，再依 文字符號的列式與運算 的規則逐步計算或判斷。",
        "a": "對照選項或計算結果，確認符合 文字符號的列式 的定義與條件。"
      },
      {
        "type": "pitfall",
        "html": "<p>有分母可整式乘最小公倍數</p><p>等號不是『算出答案』的箭頭，而是左右兩邊同值。3(x+2) 必須同時乘到 x 與 2。</p>"
      }
    ]
  },
