  "g7-2-c1/two-variable-linear-expression": {
    "title": "二元一次式",
    "chapter": "國一下｜二元一次聯立方程式",
    "section": "二元一次方程式",
    "quizId": "g7-2-c1",
    "topicId": "two-variable-linear-expression",
    "blocks": [
      {
        "type": "text",
        "html": "<p><strong>二元一次式</strong>屬於「二元一次方程式」。本題型在單元小考中固定出現一題；同一份試卷由<strong>種子碼</strong>決定使用 10 組變體中的哪一組。</p>"
      },
      {
        "type": "text",
        "html": "<p>兩條獨立的等量關係，才能共同鎖定兩個未知數。</p>"
      },
      {
        "type": "formula",
        "content": "a₁x+b₁y=c₁"
      },
      {
        "type": "text",
        "html": "<h4>解題流程</h4><ol><li>設 x、y 並定義意義</li><li>列兩個獨立方程式</li><li>選代入或消去法</li><li>求一個後回代，最後檢查兩式</li></ol>"
      },
      {
        "type": "example",
        "q": "（例）二元一次式：先讀題意，再依 二元一次方程式 的規則逐步計算或判斷。",
        "a": "對照選項或計算結果，確認符合 二元一次式 的定義與條件。"
      },
      {
        "type": "pitfall",
        "html": "<p>雞兔、票價、濃度題先列表</p><p>求出 x 後仍要回代求 y；(x,y) 的順序不能交換。兩式若其實是同一關係，可能有無限多組解；平行矛盾則無解。</p>"
      }
    ]
  },
