  "g7-2-c2/coordinate-plane": {
    "title": "直角坐標平面",
    "chapter": "國一下｜直角坐標",
    "section": "直角坐標平面",
    "quizId": "g7-2-c2",
    "topicId": "coordinate-plane",
    "blocks": [
      {
        "type": "text",
        "html": "<p><strong>直角坐標平面</strong>屬於「直角坐標平面」。本題型在單元小考中固定出現一題；同一份試卷由<strong>種子碼</strong>決定使用 10 組變體中的哪一組。</p>"
      },
      {
        "type": "text",
        "html": "<p>代數式的每一組解，都是平面上的一個點；所有解連成直線。</p>"
      },
      {
        "type": "formula",
        "content": "x 軸上的點：y=0；y 軸上的點：x=0"
      },
      {
        "type": "diagram",
        "spec": {
          "kind": "coordinatePlane",
          "points": [
            {
              "x": 0,
              "y": 0,
              "label": "O"
            },
            {
              "x": 2,
              "y": 3,
              "label": "P"
            }
          ],
          "lines": [
            {
              "x1": -3,
              "y1": -2,
              "x2": 3,
              "y2": 4
            }
          ],
          "caption": "坐標平面與點、線關係"
        }
      },
      {
        "type": "text",
        "html": "<h4>解題流程</h4><ol><li>先確認象限符號</li><li>求截距時令另一坐標為 0</li><li>檢查點是否在線上就直接代入</li><li>交點同時滿足兩線，可解聯立</li></ol>"
      },
      {
        "type": "example",
        "q": "（例）直角坐標平面：先讀題意，再依 直角坐標平面 的規則逐步計算或判斷。",
        "a": "對照選項或計算結果，確認符合 直角坐標平面 的定義與條件。"
      },
      {
        "type": "pitfall",
        "html": "<p>象限符號依序 (+,+)、(−,+)、(−,−)、(+,−)</p><p>(2,−3) 與 (−3,2) 不同。點在線上，代表把坐標代入方程式後等式成立。</p>"
      }
    ]
  },
