  "g7-2-c3/ratio-and-value": {
    "title": "比與比值",
    "chapter": "國一下｜比例",
    "section": "比與比例式",
    "quizId": "g7-2-c3",
    "topicId": "ratio-and-value",
    "blocks": [
      {
        "type": "text",
        "html": "<p><strong>比與比值</strong>屬於「比與比例式」。本題型在單元小考中固定出現一題；同一份試卷由<strong>種子碼</strong>決定使用 10 組變體中的哪一組。</p>"
      },
      {
        "type": "text",
        "html": "<p>比是兩量的相對大小；比例式是兩個比值相等。</p>"
      },
      {
        "type": "formula",
        "content": "a:b=c:d ⇔ ad=bc"
      },
      {
        "type": "text",
        "html": "<h4>解題流程</h4><ol><li>辨認對應量並統一單位</li><li>判斷固定的是比值或乘積</li><li>列比例式或 y=kx</li><li>解出後回看量是否合理</li></ol>"
      },
      {
        "type": "example",
        "q": "（例）比與比值：先讀題意，再依 比與比例式 的規則逐步計算或判斷。",
        "a": "對照選項或計算結果，確認符合 比與比值 的定義與條件。"
      },
      {
        "type": "pitfall",
        "html": "<p>地圖比例尺先統一公分</p><p>比較有單位的比要先統一單位。正比圖形通過原點；有固定起跳價的計費通常不是正比。</p>"
      }
    ]
  },
