  "g7-2-c4/linear-inequality-concept": {
    "title": "一元一次不等式",
    "chapter": "國一下｜一元一次不等式",
    "section": "一元一次不等式",
    "quizId": "g7-2-c4",
    "topicId": "linear-inequality-concept",
    "blocks": [
      {
        "type": "text",
        "html": "<p><strong>一元一次不等式</strong>屬於「一元一次不等式」。本題型在單元小考中固定出現一題；同一份試卷由<strong>種子碼</strong>決定使用 10 組變體中的哪一組。</p>"
      },
      {
        "type": "text",
        "html": "<p>不等式描述一整段可能值；乘除負數時順序會反轉。</p>"
      },
      {
        "type": "formula",
        "content": "若 a>b："
      },
      {
        "type": "text",
        "html": "<h4>解題流程</h4><ol><li>把文字條件翻成不等號</li><li>去括號、合併同類項</li><li>每次乘除負數立刻反向</li><li>畫數線並檢查端點是否包含</li></ol>"
      },
      {
        "type": "example",
        "q": "（例）一元一次不等式：先讀題意，再依 一元一次不等式 的規則逐步計算或判斷。",
        "a": "對照選項或計算結果，確認符合 一元一次不等式 的定義與條件。"
      },
      {
        "type": "pitfall",
        "html": "<p>整數個數題要檢查端點</p><p>只有乘除負數才反向，加減負數不會。『至少』是 ≥，『至多』是 ≤，『不超過』也是 ≤。</p>"
      }
    ]
  },
