  "g7-2-c6/figure-notation": {
    "title": "點、線、角、多邊形的標記與對角線",
    "chapter": "國一下｜線對稱與三視圖",
    "section": "簡單圖形與垂直、平分",
    "quizId": "g7-2-c6",
    "topicId": "figure-notation",
    "blocks": [
      {
        "type": "text",
        "html": "<p><strong>點、線、角、多邊形的標記與對角線</strong>屬於「簡單圖形與垂直、平分」。本題型在單元小考中固定出現一題；同一份試卷由<strong>種子碼</strong>決定使用 10 組變體中的哪一組。</p>"
      },
      {
        "type": "text",
        "html": "<p>幾何先看定義與關係，再計算；圖看起來像，不代表條件成立。</p>"
      },
      {
        "type": "formula",
        "content": "對頂角相等"
      },
      {
        "type": "diagram",
        "spec": {
          "kind": "coordinatePlane",
          "points": [
            {
              "x": 0,
              "y": 0,
              "label": "O"
            },
            {
              "x": 2,
              "y": 3,
              "label": "P"
            }
          ],
          "lines": [
            {
              "x1": -3,
              "y1": -2,
              "x2": 3,
              "y2": 4
            }
          ],
          "caption": "坐標平面與點、線關係"
        }
      },
      {
        "type": "text",
        "html": "<h4>解題流程</h4><ol><li>把已知角與平行、垂直記號標上</li><li>找對頂、互補、互餘</li><li>需要等距時想垂直平分線或角平分線</li><li>每一步寫出使用的性質</li></ol>"
      },
      {
        "type": "example",
        "q": "（例）點、線、角、多邊形的標記與對角線：先讀題意，再依 簡單圖形與垂直、平分 的規則逐步計算或判斷。",
        "a": "對照選項或計算結果，確認符合 點、線、角、多邊形的標記與對角線 的定義與條件。"
      },
      {
        "type": "pitfall",
        "html": "<p>延長線常製造線性對角</p><p>圖形常不是按比例畫，不能用目測或量圖代替推理。線段有兩端點，射線一端，直線向兩側無限延伸。</p>"
      }
    ]
  },
