  "g7-2-c5/contingency-frequency-table": {
    "title": "列聯表與次數分配表",
    "chapter": "國一下｜統計圖表",
    "section": "統計圖表",
    "quizId": "g7-2-c5",
    "topicId": "contingency-frequency-table",
    "blocks": [
      {
        "type": "text",
        "html": "<p><strong>列聯表與次數分配表</strong>屬於「統計圖表」。本題型在單元小考中固定出現一題；同一份試卷由<strong>種子碼</strong>決定使用 10 組變體中的哪一組。</p>"
      },
      {
        "type": "text",
        "html": "<p>平均數看整體平衡，中位數看排序中心，眾數看最常出現。</p>"
      },
      {
        "type": "formula",
        "content": "平均數＝[[frac:總和|個數]]"
      },
      {
        "type": "diagram",
        "spec": {
          "kind": "boxPlot",
          "caption": "資料分布的五數摘要"
        }
      },
      {
        "type": "text",
        "html": "<h4>解題流程</h4><ol><li>讀清資料單位與樣本數</li><li>中位數務必先排序</li><li>次數表用加權總和</li><li>比較圖表時看尺度是否一致</li></ol>"
      },
      {
        "type": "example",
        "q": "（例）列聯表與次數分配表：先讀題意，再依 統計圖表 的規則逐步計算或判斷。",
        "a": "對照選項或計算結果，確認符合 列聯表與次數分配表 的定義與條件。"
      },
      {
        "type": "pitfall",
        "html": "<p>平均數×個數=總和，可處理增刪資料</p><p>長條圖縱軸若不從 0 開始，視覺差距可能被放大。圓餅圖角度 = 比例×360°。</p>"
      }
    ]
  },
