  "g8-1-c1/common-multiplication-formulas": {
    "title": "常用的乘法公式",
    "chapter": "國二上｜乘法公式與多項式",
    "section": "乘法公式",
    "quizId": "g8-1-c1",
    "topicId": "common-multiplication-formulas",
    "blocks": [
      {
        "type": "text",
        "html": "<p><strong>常用的乘法公式</strong>屬於「乘法公式」。本題型在單元小考中固定出現一題；同一份試卷由<strong>種子碼</strong>決定使用 10 組變體中的哪一組。</p>"
      },
      {
        "type": "text",
        "html": "<p>多項式運算是分配律的系統化；公式是常見展開結果，不是魔法。</p>"
      },
      {
        "type": "formula",
        "content": "(a+b)²=a²+2ab+b²"
      },
      {
        "type": "text",
        "html": "<h4>解題流程</h4><ol><li>先判斷能否套公式</li><li>不能套就逐項分配</li><li>合併同類項並按次方排列</li><li>代回簡單數值檢查符號</li></ol>"
      },
      {
        "type": "example",
        "q": "（例）常用的乘法公式：先讀題意，再依 乘法公式 的規則逐步計算或判斷。",
        "a": "對照選項或計算結果，確認符合 常用的乘法公式 的定義與條件。"
      },
      {
        "type": "pitfall",
        "html": "<p>接近整數的平方用和平方或差平方</p><p>(a+b)² ≠ a²+b²，中間一定有 2ab。減去多項式時，括號內每一項都要變號。</p>"
      }
    ]
  },
