  "g8-1-c2/sqrt-meaning": {
    "title": "平方根的意義",
    "chapter": "國二上｜平方根與畢氏定理",
    "section": "平方根與近似值",
    "quizId": "g8-1-c2",
    "topicId": "sqrt-meaning",
    "blocks": [
      {
        "type": "text",
        "html": "<p><strong>平方根的意義</strong>屬於「平方根與近似值」。本題型在單元小考中固定出現一題；同一份試卷由<strong>種子碼</strong>決定使用 10 組變體中的哪一組。</p>"
      },
      {
        "type": "text",
        "html": "<p>平方根回答『哪個數平方後得到它』；畢氏定理連結直角三角形三邊。</p>"
      },
      {
        "type": "formula",
        "content": "(√a)²=a（a≥0）"
      },
      {
        "type": "text",
        "html": "<h4>解題流程</h4><ol><li>根式先分解完全平方因數</li><li>幾何題先找直角與斜邊</li><li>代入平方關係後解非負長度</li><li>用最大邊平方與另兩邊平方和檢查</li></ol>"
      },
      {
        "type": "example",
        "q": "（例）平方根的意義：先讀題意，再依 平方根與近似值 的規則逐步計算或判斷。",
        "a": "對照選項或計算結果，確認符合 平方根的意義 的定義與條件。"
      },
      {
        "type": "pitfall",
        "html": "<p>常見 3-4-5、5-12-13、8-15-17</p><p>√9=3，不是 ±3；但 x²=9 的解才是 ±3。只有先確認直角，才能直接使用畢氏定理。</p>"
      }
    ]
  },
