  "g8-1-c3/factor-and-multiple": {
    "title": "因式與倍式",
    "chapter": "國二上｜因式分解",
    "section": "因式分解",
    "quizId": "g8-1-c3",
    "topicId": "factor-and-multiple",
    "blocks": [
      {
        "type": "text",
        "html": "<p><strong>因式與倍式</strong>屬於「因式分解」。本題型在單元小考中固定出現一題；同一份試卷由<strong>種子碼</strong>決定使用 10 組變體中的哪一組。</p>"
      },
      {
        "type": "text",
        "html": "<p>因式分解是多項式乘法的逆運算；目標是寫成乘積。</p>"
      },
      {
        "type": "formula",
        "content": "ab+ac=a(b+c)"
      },
      {
        "type": "text",
        "html": "<h4>解題流程</h4><ol><li>先提最大公因式</li><li>數項判平方差或完全平方</li><li>二次三項式找和為中項、積為常數的兩數</li><li>展開檢查</li></ol>"
      },
      {
        "type": "example",
        "q": "（例）因式與倍式：先讀題意，再依 因式分解 的規則逐步計算或判斷。",
        "a": "對照選項或計算結果，確認符合 因式與倍式 的定義與條件。"
      },
      {
        "type": "pitfall",
        "html": "<p>第一眼永遠先找公因式</p><p>分解後必須是乘法形式；x²−9＝(x−3)(x＋3)，不能停在 x(x−[[frac:9|x]])。共同負號提出可讓首項為正、較易辨識。</p>"
      }
    ]
  },
