  "g8-1-c4/quadratic-equation-concept": {
    "title": "一元二次方程式",
    "chapter": "國二上｜一元二次方程式",
    "section": "因式分解法解一元二次方程式",
    "quizId": "g8-1-c4",
    "topicId": "quadratic-equation-concept",
    "blocks": [
      {
        "type": "text",
        "html": "<p><strong>一元二次方程式</strong>屬於「因式分解法解一元二次方程式」。本題型在單元小考中固定出現一題；同一份試卷由<strong>種子碼</strong>決定使用 10 組變體中的哪一組。</p>"
      },
      {
        "type": "text",
        "html": "<p>先整理成 ax²+bx+c=0，再選分解、開平方或公式解。</p>"
      },
      {
        "type": "formula",
        "content": "ax²＋bx＋c＝0（a≠0）"
      },
      {
        "type": "text",
        "html": "<h4>解題流程</h4><ol><li>移項整理成標準式 =0</li><li>先試提公因式與因式分解</li><li>不易分解再用公式</li><li>檢查兩根與情境限制</li></ol>"
      },
      {
        "type": "example",
        "q": "（例）一元二次方程式：先讀題意，再依 因式分解法解一元二次方程式 的規則逐步計算或判斷。",
        "a": "對照選項或計算結果，確認符合 一元二次方程式 的定義與條件。"
      },
      {
        "type": "pitfall",
        "html": "<p>看到 x²＝k 直接 x＝±√k</p><p>等式一邊不是 0 時不能直接令每個因式為 0。開平方要記得 ±，但長度情境再排除負值。</p>"
      }
    ]
  },
