  "g8-2-c1/sequence-concept": {
    "title": "數列",
    "chapter": "國二下｜數列與級數",
    "section": "等差數列",
    "quizId": "g8-2-c1",
    "topicId": "sequence-concept",
    "blocks": [
      {
        "type": "text",
        "html": "<p><strong>數列</strong>屬於「等差數列」。本題型在單元小考中固定出現一題；同一份試卷由<strong>種子碼</strong>決定使用 10 組變體中的哪一組。</p>"
      },
      {
        "type": "text",
        "html": "<p>數列題先找『位置 n』與『數值』的關係，不只盯著前幾項。</p>"
      },
      {
        "type": "formula",
        "content": "等差數列：aₙ＝a₁＋(n−1)d"
      },
      {
        "type": "text",
        "html": "<h4>解題流程</h4><ol><li>列出項次 n 與項值</li><li>算相鄰差或比</li><li>確認規律至少符合三項</li><li>代公式並注意 n−1</li></ol>"
      },
      {
        "type": "example",
        "q": "（例）數列：先讀題意，再依 等差數列 的規則逐步計算或判斷。",
        "a": "對照選項或計算結果，確認符合 數列 的定義與條件。"
      },
      {
        "type": "pitfall",
        "html": "<p>圖形題分固定部分＋每層新增</p><p>第 n 項不是前 n 項和。等比公比可為負，但除數不能是 0。會考常把規律藏在座位、階梯、點陣中。</p>"
      }
    ]
  },
