  "g8-2-c2/function-concept": {
    "title": "函數",
    "chapter": "國二下｜線型函數",
    "section": "認識函數",
    "quizId": "g8-2-c2",
    "topicId": "function-concept",
    "blocks": [
      {
        "type": "text",
        "html": "<p><strong>函數</strong>屬於「認識函數」。本題型在單元小考中固定出現一題；同一份試卷由<strong>種子碼</strong>決定使用 10 組變體中的哪一組。</p>"
      },
      {
        "type": "text",
        "html": "<p>斜率描述每增加 1 單位 x，y 改變多少；截距描述起點。</p>"
      },
      {
        "type": "formula",
        "content": "m＝[[frac:y₂−y₁|x₂−x₁]]"
      },
      {
        "type": "text",
        "html": "<h4>解題流程</h4><ol><li>從情境辨認固定量與單位變化量</li><li>求斜率並標單位</li><li>代一點求 b</li><li>用另一點或圖形驗證</li></ol>"
      },
      {
        "type": "example",
        "q": "（例）函數：先讀題意，再依 認識函數 的規則逐步計算或判斷。",
        "a": "對照選項或計算結果，確認符合 函數 的定義與條件。"
      },
      {
        "type": "pitfall",
        "html": "<p>每單位費用就是斜率</p><p>斜率分子分母順序必須對應同一方向。m>0 右上升，m<0 右下降，m=0 水平。固定費＋單價×用量是典型線型函數。</p>"
      }
    ]
  },
