  "g8-2-c3/angle-concept": {
    "title": "角",
    "chapter": "國二下｜三角形的基本性質",
    "section": "角與尺規作圖",
    "quizId": "g8-2-c3",
    "topicId": "angle-concept",
    "blocks": [
      {
        "type": "text",
        "html": "<p><strong>角</strong>屬於「角與尺規作圖」。本題型在單元小考中固定出現一題；同一份試卷由<strong>種子碼</strong>決定使用 10 組變體中的哪一組。</p>"
      },
      {
        "type": "text",
        "html": "<p>全等要靠足夠條件；對應順序一旦弄錯，後面全錯。</p>"
      },
      {
        "type": "formula",
        "content": "三角形內角和=180°"
      },
      {
        "type": "text",
        "html": "<h4>解題流程</h4><ol><li>標出已知邊角與公共邊</li><li>判斷是否有平行線提供等角</li><li>選正確全等條件</li><li>依對應順序推出所求</li></ol>"
      },
      {
        "type": "example",
        "q": "（例）角：先讀題意，再依 角與尺規作圖 的規則逐步計算或判斷。",
        "a": "對照選項或計算結果，確認符合 角 的定義與條件。"
      },
      {
        "type": "pitfall",
        "html": "<p>公共邊常是隱藏條件</p><p>AAA 只能保證相似，不能全等；SSA 通常不足。SAS 的角必須是兩邊夾角。全等符號書寫順序要對應頂點。</p>"
      }
    ]
  },
