  "g8-2-c4/parallel-lines-concept": {
    "title": "平行線",
    "chapter": "國二下｜平行與四邊形",
    "section": "平行線與截角性質",
    "quizId": "g8-2-c4",
    "topicId": "parallel-lines-concept",
    "blocks": [
      {
        "type": "text",
        "html": "<p><strong>平行線</strong>屬於「平行線與截角性質」。本題型在單元小考中固定出現一題；同一份試卷由<strong>種子碼</strong>決定使用 10 組變體中的哪一組。</p>"
      },
      {
        "type": "text",
        "html": "<p>平行線提供角關係；對角線則是辨識特殊四邊形的捷徑。</p>"
      },
      {
        "type": "formula",
        "content": "平行四邊形面積＝底×高"
      },
      {
        "type": "diagram",
        "spec": {
          "kind": "parallelLines",
          "caption": "平行線被截線所形成的角度"
        }
      },
      {
        "type": "text",
        "html": "<h4>解題流程</h4><ol><li>先寫出四邊形已知類型</li><li>用平行線找角、用對角線找全等</li><li>面積題確認高必須垂直</li><li>需要判定時檢查充分條件</li></ol>"
      },
      {
        "type": "example",
        "q": "（例）平行線：先讀題意，再依 平行線與截角性質 的規則逐步計算或判斷。",
        "a": "對照選項或計算結果，確認符合 平行線 的定義與條件。"
      },
      {
        "type": "pitfall",
        "html": "<p>同底同高三角形面積相等</p><p>對角線等長不一定是矩形，還需知道是平行四邊形；對角線垂直不一定是菱形。證明題要從已知類型逐步使用性質。</p>"
      }
    ]
  },
