  "g9-1-c1/continued-ratio-concept": {
    "title": "連比",
    "chapter": "國三上｜連比與相似形",
    "section": "連比與連比例式",
    "quizId": "g9-1-c1",
    "topicId": "continued-ratio-concept",
    "blocks": [
      {
        "type": "text",
        "html": "<p><strong>連比</strong>屬於「連比與連比例式」。本題型在單元小考中固定出現一題；同一份試卷由<strong>種子碼</strong>決定使用 10 組變體中的哪一組。</p>"
      },
      {
        "type": "text",
        "html": "<p>相似保角度、邊成比例；長度、面積、體積的倍率分別是一、二、三次方。</p>"
      },
      {
        "type": "formula",
        "content": "對應邊比=k"
      },
      {
        "type": "text",
        "html": "<h4>解題流程</h4><ol><li>先找等角確定對應頂點</li><li>按同一順序列比例</li><li>判斷題目問長、面積或體積</li><li>代回尺度檢查</li></ol>"
      },
      {
        "type": "example",
        "q": "（例）連比：先讀題意，再依 連比與連比例式 的規則逐步計算或判斷。",
        "a": "對照選項或計算結果，確認符合 連比 的定義與條件。"
      },
      {
        "type": "pitfall",
        "html": "<p>平行線一出現先找 AA 相似</p><p>對應邊順序要一致；面積比不能直接當邊長比。圖形方向可旋轉或翻轉，相似關係仍存在。</p>"
      }
    ]
  },
