  "g9-1-c3/geometry-proof-application": {
    "title": "幾何證明與應用",
    "chapter": "國三上｜推理證明與三角形的心",
    "section": "推理證明",
    "quizId": "g9-1-c3",
    "topicId": "geometry-proof-application",
    "blocks": [
      {
        "type": "text",
        "html": "<p><strong>幾何證明與應用</strong>屬於「推理證明」。本題型在單元小考中固定出現一題；同一份試卷由<strong>種子碼</strong>決定使用 10 組變體中的哪一組。</p>"
      },
      {
        "type": "text",
        "html": "<p>證明不是寫結果；是把已知、性質與結論串成每一步都站得住的鏈。</p>"
      },
      {
        "type": "formula",
        "content": "外心：OA=OB=OC"
      },
      {
        "type": "diagram",
        "spec": {
          "kind": "triangle",
          "caption": "三角形邊角關係示意"
        }
      },
      {
        "type": "text",
        "html": "<h4>解題流程</h4><ol><li>寫已知與欲證</li><li>把結論拆成可證的小目標</li><li>尋找全等、相似、平行或等距</li><li>每個等式旁註理由，最後回扣結論</li></ol>"
      },
      {
        "type": "example",
        "q": "（例）幾何證明與應用：先讀題意，再依 推理證明 的規則逐步計算或判斷。",
        "a": "對照選項或計算結果，確認符合 幾何證明與應用 的定義與條件。"
      },
      {
        "type": "pitfall",
        "html": "<p>欲證邊相等常證全等</p><p>外心不一定在三角形內：銳角在內、直角在斜邊中點、鈍角在外。重心 2:1 是從頂點到重心 : 重心到中點。</p>"
      }
    ]
  },
