  "g9-2-c1/quadratic-function-concept": {
    "title": "二次函數",
    "chapter": "國三下｜二次函數",
    "section": "二次函數的圖形",
    "quizId": "g9-2-c1",
    "topicId": "quadratic-function-concept",
    "blocks": [
      {
        "type": "text",
        "html": "<p><strong>二次函數</strong>屬於「二次函數的圖形」。本題型在單元小考中固定出現一題；同一份試卷由<strong>種子碼</strong>決定使用 10 組變體中的哪一組。</p>"
      },
      {
        "type": "text",
        "html": "<p>二次函數的圖形是拋物線；頂點與對稱軸決定整張圖的骨架。</p>"
      },
      {
        "type": "formula",
        "content": "y＝a(x−h)²＋k"
      },
      {
        "type": "diagram",
        "spec": {
          "kind": "coordinatePlane",
          "points": [
            {
              "x": 0,
              "y": 0,
              "label": "O"
            },
            {
              "x": 2,
              "y": 3,
              "label": "P"
            }
          ],
          "lines": [
            {
              "x1": -3,
              "y1": -2,
              "x2": 3,
              "y2": 4
            }
          ],
          "caption": "坐標平面與點、線關係"
        }
      },
      {
        "type": "text",
        "html": "<h4>解題流程</h4><ol><li>盡量配成頂點式</li><li>讀出開口、頂點、對稱軸</li><li>求截距就令 x=0 或 y=0</li><li>情境最佳化要檢查定義域</li></ol>"
      },
      {
        "type": "example",
        "q": "（例）二次函數：先讀題意，再依 二次函數的圖形 的規則逐步計算或判斷。",
        "a": "對照選項或計算結果，確認符合 二次函數 的定義與條件。"
      },
      {
        "type": "pitfall",
        "html": "<p>同高兩點的 x 平均就是對稱軸</p><p>y=ax² 的頂點才固定在原點。函數值相等的兩點通常關於對稱軸對稱；x 截距是解 y=0，不是看 b。</p>"
      }
    ]
  },
