  "g9-2-c3/plane-plane": {
    "title": "平面與平面",
    "chapter": "國三下｜立體圖形",
    "section": "空間中的線與平面",
    "quizId": "g9-2-c3",
    "topicId": "plane-plane",
    "blocks": [
      {
        "type": "text",
        "html": "<p><strong>平面與平面</strong>屬於「空間中的線與平面」。本題型在單元小考中固定出現一題；同一份試卷由<strong>種子碼</strong>決定使用 10 組變體中的哪一組。</p>"
      },
      {
        "type": "text",
        "html": "<p>先辨認底面與高，再決定是『包表面』還是『裝容量』。</p>"
      },
      {
        "type": "formula",
        "content": "柱體 V＝Bh"
      },
      {
        "type": "diagram",
        "spec": {
          "kind": "solidPrism",
          "caption": "立體圖形的面與棱"
        }
      },
      {
        "type": "text",
        "html": "<h4>解題流程</h4><ol><li>畫剖面或展開圖</li><li>標底面 B、垂直高 h</li><li>體積與表面積分開計算</li><li>最後檢查平方與立方單位</li></ol>"
      },
      {
        "type": "example",
        "q": "（例）平面與平面：先讀題意，再依 空間中的線與平面 的規則逐步計算或判斷。",
        "a": "對照選項或計算結果，確認符合 平面與平面 的定義與條件。"
      },
      {
        "type": "pitfall",
        "html": "<p>容量換算：1 cm³=1 mL</p><p>斜高不是圓錐的垂直高。容器無蓋時少一個面；挖洞可能增加內側表面。長度倍率 k 會讓體積變 k³。</p>"
      }
    ]
  },
