        "type": "text",
        "html": "<p><strong>圓錐表面積的計算</strong>屬於「角錐與圓錐」。本題型在單元小考中固定出現一題；同一份試卷由<strong>種子碼</strong>決定使用 10 組變體中的哪一組。</p>"
